Translate("frFR", "kreldig-ungor", {
	title = "Kreldig Ungor",
	subtitle = "Agent de Reclaimers Inc.",
	found = "Combe de Nijel",
	hint = [=[Parlez au nain de la Combe de Nijel qui retrouve ce que d'autres ont perdu.]=],
	allegiance = "Reclaimers Inc. · Royaume d'Ironforge",
	aliases = { "Kreldig" },
	sections = {
		{
			title = "Résumé",
			text = [=[Kreldig Ungor est un {link:dwarves}nain{/link} de Reclaimers Inc., une compagnie d'{link:ironforge}Ironforge{/link} qui retrouve les objets perdus pour ceux qui peuvent payer. Il a été envoyé en {link:desolace}Désolace{/link} avec plus de travail que de bras, et il ne cache pas combien il aime peu l'endroit, ni le camp. Ses clients sont loin : un mage de {link:stormwind-city}Stormwind{/link} qui a perdu un coffre au profit de géants des mers, et un {link:gnomes}gnome{/link} de {link:dun-morogh}Dun Morogh{/link} qui veut les composants les plus étranges dont un nain ait jamais entendu parler.]=],
		},
		{
			title = "Importance",
			text = [=[Grâce aux commissions de Kreldig, les dangers de {link:desolace}Désolace{/link} apparaissent un à un : les nagas de la côte, les satyres du nord-est, et des démons dont il ignorait la présence.]=],
		},
		{
			title = "Hauts faits",
			text = [=[• Il cherche le coffre perdu du mage Karnitol, et en suit le contenu jusqu'aux nagas de l'{link:ranazjar-isle}Ile de Ranazjar{/link}.
• Il rassemble cornes de {link:satyrs}satyre{/link}, venin de scorpashi, peau de kodo et restes de démons pour le mage {link:gnomes}gnome{/link} Leftwitch.
• Il se demande à voix haute pourquoi les démons sont venus en {link:desolace}Désolace{/link}, et comment.]=],
		},
	},
	mentions = {
		{
			text = [=[Les affaires des Reclaimers en {link:desolace}Désolace{/link}]=],
		},
		{ text = "Le naufrage du Karnitol" },
		{ text = "Le naufrage du Karnitol, le trésor des nagas" },
		{
