Translate("frFR", "vahlarriel-demonslayer", {
	title = "Vahlarriel Demonslayer",
	subtitle = "Agente de Darnassus",
	found = "Combe de Nijel",
	hint = [=[Parlez à l'elfe de la nuit de la Combe de Nijel qui cherche deux nobles disparus.]=],
	allegiance = "Darnassus · Alliance",
	aliases = { "Vahlarriel" },
	sections = {
		{
			title = "Résumé",
			text = [=[Vahlarriel Demonslayer est une {link:night-elves}elfe de la nuit{/link} envoyée de {link:darnassus}Darnassus{/link} pour retrouver deux enfants disparus de la maison Malem, une famille de marchands dont le père craint le pire. Le frère et la sœur, {link:tyranis-malem}Tyranis{/link} et {link:dalinda-malem}Dalinda{/link}, traversèrent les {link:stonetalon-mountains}Serres-Rocheuses{/link} quelques semaines plus tôt et disparurent en {link:desolace}Désolace{/link}. Les ordres de Vahlarriel portent un second but, plus discret. Ses supérieurs se soucient surtout de Dalinda. Tyranis doit être jugé avant d'être ramené chez lui.]=],
		},
		{
			title = "Importance",
			text = [=[La recherche de Vahlarriel révèle jusqu'où s'étend la {link:burning-blade}Lame ardente{/link}, et comment même un enfant des {link:night-elves}elfes de la nuit{/link} peut être attiré par la magie que son peuple interdit.]=],
		},
		{
			title = "Hauts faits",
			text = [=[• Elle demande des nouvelles du chariot des Malem dans le nord de {link:desolace}Désolace{/link}.
• Elle suit les traces vers le sud jusqu'à la {link:thunder-axe-fortress}Forteresse de Hache-Tonnerre{/link}.
• Elle rapporte chaque tournant de la recherche à ses supérieurs de {link:darnassus}Darnassus{/link}.]=],
		},
	},
	chapters = {
		{
			title = "Le chariot vide",
			hint = [=[Trouvez le chariot de la maison Malem dans le nord de Désolace.]=],
			text = [=[Le chariot fut trouvé brisé. Des sorts et des lames l'avaient frappé, le combat avait été bref, et aucun corps ne gisait à proximité. À côté se trouvaient un pendentif, et des traces qui menaient vers le sud, vers la fumée d'un grand fort. Vahlarriel connaissait le lieu de réputation. C'était l'antre d'orcs qui s'étaient livrés aux démons.]=],
		},
		{
			title = "Le sort des Malem",
			hint = [=[Faites sortir Dalinda Malem saine et sauve de la Forteresse de Hache-Tonnerre.]=],
			text = [=[{link:dalinda-malem}Dalinda{/link} revint à la {link:nijels-point}Combe de Nijel{/link} sur ses propres jambes, et Vahlarriel y vit une grâce. {link:tyranis-malem}Tyranis{/link} ne revint pas. Il avait recherché la faveur des cultistes qui l'avaient pris, et il mourut parmi eux. La honte de ses choix accompagnerait sa sœur jusque chez elle, et elle seule devrait la porter devant son peuple.]=],
		},
	},
	mentions = {
		{ text = "La recherche de Vahlarriel" },
		{ text = "La recherche de Vahlarriel, le pendentif et les traces" },
		{ text = "La recherche de Vahlarriel, la forteresse" },
		{ text = "Retour auprès de Vahlarriel" },
	},
	bonds = {
		{ id = "dalinda-malem", name = "Dalinda Malem", note = "la noble qu'elle cherchait" },
		{ id = "tyranis-malem", name = "Tyranis Malem", note = "le noble qu'elle devait juger" },
		{ id = "kreldig-ungor", name = "Kreldig Ungor", note = "partage le camp" },
	},
})

Translate("frFR", "dalinda-malem", {
