Translate("frFR", "captain-pentigast", {
	title = "Capitaine Pentigast",
	subtitle = "Commandant de la Combe de Nijel",
	found = "Combe de Nijel",
	hint = [=[Parlez au capitaine qui commande les soldats de la Combe de Nijel.]=],
	allegiance = "Alliance",
	aliases = { "Pentigast" },
	sections = {
		{
			title = "Résumé",
			text = [=[Le capitaine Pentigast commande les soldats de l'Alliance à la {link:nijels-point}Combe de Nijel{/link}. Il observe les guerres des centaures d'un œil froid. Il croit que le clan qui l'emportera, quel qu'il soit, débordera hors de {link:desolace}Désolace{/link} et menacera les places fortes de l'{link:alliance}Alliance{/link}, et il n'entend pas laisser faire. Sa réponse est la politique : prendre parti, gagner la confiance d'un clan, et apprendre comment les vaincre tous.]=],
		},
		{
			title = "Importance",
			text = [=[Pentigast fait entrer l'{link:alliance}Alliance{/link} dans le même jeu que celui que joue la {link:horde}Horde{/link} au {link:ghost-walker-post}Poste de Rôdeur-fantôme{/link}. Les deux camps courtisent désormais les clans avec le sang d'autres centaures.]=],
		},
		{
			title = "Hauts faits",
			text = [=[• Il envoie des émissaires auprès d'{link:uthek-the-wise}Uthek la Sage{/link}, des Gelkis, ou de {link:warug}Warug{/link}, des Magram.]=],
		},
	},
	mentions = {
		{ text = "Une étrange alliance" },
		{ text = "Politique brutale" },
	},
	bonds = {
		{ id = "uthek-the-wise", name = "Uthek la Sage", note = "une alliée possible" },
		{ id = "warug", name = "Warug", note = "un allié possible" },
		{ id = "corporal-melkins", name = "Caporal Melkins", note = "sert sous ses ordres" },
	},
})

Translate("frFR", "corporal-melkins", {
	title = "Caporal Melkins",
	subtitle = "Soldat de la Combe de Nijel",
	found = "Combe de Nijel",
	hint = [=[Parlez au caporal de la Combe de Nijel qui compte les oreilles de centaures.]=],
	allegiance = "Alliance",
	sections = {
