	},
})

Translate("frFR", "keeper-marandis", {
	title = "Gardien Marandis",
	subtitle = "Gardien du Cercle cénarien",
	found = "Combe de Nijel",
	hint = [=[Parlez au gardien de la Combe de Nijel venu à cause de Maraudon.]=],
	allegiance = "Cercle cénarien",
	aliases = { "Marandis" },
	sections = {
		{
			title = "Résumé",
			text = [=[Le gardien Marandis vint en {link:desolace}Désolace{/link} pour {red:maraudon}Maraudon{/red}. Il parle à qui veut l'entendre de la princesse Theradras, une force de la terre élémentaire apparentée d'une manière ou d'une autre aux Dieux très anciens, que rechercha Zaetar, le premier fils de {link:cenarius}Cenarius{/link}. Les centaures furent leurs enfants, et les centaures tuèrent leur père. Theradras garde aujourd'hui ses restes, et le gardien veut qu'on les ramène chez lui.]=],
		},
		{
			title = "Importance",
			text = [=[Marandis porte le chagrin du {link:cenarion-circle}Cercle cénarien{/link}. Zaetar était le frère de {link:keeper-remulos}Remulos{/link}, et les druides ne l'ont jamais oublié.]=],
		},
		{
			title = "Hauts faits",
			text = [=[• Il demande des champions assez forts pour tuer Theradras et récupérer les restes de Zaetar.
• Il est conseillé par {link:selendra}Selendra{/link}, qui fait le même travail à l'autre bout du pays, du côté de la {link:horde}Horde{/link}.]=],
		},
	},
	mentions = {
		{ text = "Corruption de la terre et de la graine" },
	},
	bonds = {
		{ id = "selendra", name = "Selendra", note = "partage sa cause" },
		{ id = "talendria", name = "Talendria", note = "druide comme lui à la Combe de Nijel" },
	},
})

Translate("frFR", "selendra", {
	title = "Selendra",
	subtitle = "Druidesse du Cercle cénarien",
	found = "Un camp de druides près de Proie-de-l'Ombre",
	hint = "Parlez à la druidesse qui campe au sud de Proie-de-l'Ombre.",
	allegiance = "Cercle cénarien",
	sections = {
		{
			title = "Résumé",
			text = [=[Selendra est une druidesse du {link:cenarion-circle}Cercle cénarien{/link} qui attend près de {link:shadowprey-village}Proie-de-l'Ombre{/link}. Comme le gardien {link:keeper-marandis}Marandis{/link}, elle cherche les restes de Zaetar, et comme lui elle doit demander de l'aide aux peuples mortels. Elle préférerait livrer elle-même la bataille. Elle dit que Zaetar, frère de {link:keeper-remulos}Remulos{/link}, apporta beaucoup de souffrance au monde et que cela prit fin avec sa mort, et elle espère que sa requête n'en causera pas davantage.]=],
