		{
			title = "Importance",
			text = [=[Selendra montre comment le Cercle se tient entre l'{link:alliance}Alliance{/link} et la {link:horde}Horde{/link}, demandant la même aide aux deux.]=],
		},
		{
			title = "Hauts faits",
			text = [=[• Elle demande que la princesse Theradras soit tuée, afin que les restes de Zaetar puissent être rapportés aux {link:stonetalon-mountains}Serres-Rocheuses{/link}.]=],
		},
	},
	mentions = {
		{ text = "Corruption de la terre et de la graine" },
	},
	bonds = {
		{ id = "keeper-marandis", name = "Gardien Marandis", note = "partage sa cause" },
	},
})

Translate("frFR", "talendria", {
