	hint = [=[Parlez à l'elfe de la nuit de la Combe de Nijel qui étudie les plantes corrompues de Maraudon.]=],
	allegiance = "Alliance",
	sections = {
		{
			title = "Résumé",
			text = [=[Talendria étudie la corruption au sein de {red:maraudon}Maraudon{/red}. Un {link:satyrs}satyre{/link} appelé Vyletongue a empoisonné ses cavernes et freiné la croissance de chaque plante qui s'y trouve. Elle a fabriqué une fiole dont l'enduit change l'eau corrompue en remède, et elle espère que les plantes de Maraudon pourront encore être guéries, même si Vyletongue les tient toujours.]=],
