	},
	bonds = {
		{ id = "keeper-marandis", name = "Gardien Marandis", note = "druide comme elle à la Combe de Nijel" },
		{ id = "vark-battlescar", name = "Vark Battlescar", note = "fait le même travail pour la Horde" },
	},
})

Translate("frFR", "vark-battlescar", {
