	subtitle = "De Proie-de-l'Ombre",
	found = "Proie-de-l'Ombre",
	hint = [=[Parlez à celui qui, à Proie-de-l'Ombre, cherche à soigner les plantes de Maraudon.]=],
	allegiance = "Horde",
	sections = {
		{
			title = "Résumé",
			text = [=[Vark Battlescar, de {link:shadowprey-village}Proie-de-l'Ombre{/link}, s'est chargé du même labeur que {link:talendria}Talendria{/link} de la {link:nijels-point}Combe de Nijel{/link}. Lui aussi sait que le {link:satyrs}satyre{/link} Vyletongue a corrompu les cavernes de {red:maraudon}Maraudon{/red}, et lui aussi offre une fiole pour changer leur poison en remède. Que la {link:horde}Horde{/link} et l'{link:alliance}Alliance{/link} étudient la même maladie depuis des rives opposées est un petit signe de l'importance de la tombe.]=],
