		},
	},
	mentions = {
		{ text = "La corruption de Vyletongue" },
	},
	bonds = {
		{ id = "talendria", name = "Talendria", note = "fait le même travail pour l'Alliance" },
	},
})

Translate("frFR", "cavindra", {
	title = "Cavindra",
	subtitle = "Sœur de Celebras",
	found = "Près de l'entrée de Maraudon",
	hint = [=[Cherchez celle qui, près des portes de Maraudon, pleure son frère.]=],
	allegiance = "Famille de Celebras",
	sections = {
		{
			title = "Résumé",
			text = [=[Cavindra attend près des portes de {red:maraudon}Maraudon{/red}, s'éveillant de ce qu'elle appelle un cauchemar qui semblait sans fin. Son frère Celebras erre aveuglément à l'intérieur, maudit par la corruption. Le {link:satyrs}satyre{/link} seigneur Vyletongue et un symbole vivant de sa corruption nommé Noxxion ont volé les deux moitiés du sceptre de son frère. Elle veut que les morceaux soient retrouvés, et que son frère soit atteint, par quelque moyen que ce soit.]=],
		},
		{
			title = "Importance",
			text = [=[Le chagrin de Cavindra est le premier signe, pour les étrangers, que la tombe de Zaetar abrite plus que des centaures.]=],
