		{
			title = "Hauts faits",
			text = [=[• Elle parle de Vyletongue et de Noxxion, et du sceptre volé de Celebras.]=],
		},
	},
	mentions = {
		{ text = "Les légendes de Maraudon" },
	},
	bonds = {
		{ id = "celebras-the-cursed", name = "Celebras le Maudit", note = "son frère" },
	},
})

Translate("frFR", "centaur-pariah", {
	title = "Paria centaure",
	subtitle = "Exilé des clans",
	found = "Il erre dans le sud de Désolace",
	hint = [=[Cherchez le centaure proscrit qui erre seul dans les collines du sud.]=],
	allegiance = "Aucune, chassé par les clans",
	aliases = { "le Paria" },
	sections = {
		{
			title = "Résumé",
			text = [=[Le Paria centaure fut chassé par son peuple comme hérétique. Il croit encore ce qui lui valut l'exil : que les clans peuvent être forgés en une seule grande tribu. Pour commencer cette œuvre, il a besoin d'un étranger, quelqu'un sans clan, prêt à poser le pied dans les salles sacrées de {red:maraudon}Maraudon{/red}, où seuls les centaures les plus dévots peuvent entrer.]=],
		},
		{
			title = "Importance",
			text = [=[Dans un pays où les clans vivent pour s'entre-tuer, le Paria est le seul {link:centaurs}centaure{/link} qui rêve de leur union. Ce rêve est peut-être la chose la plus dangereuse de {link:desolace}Désolace{/link}, car tous les autres peuples espèrent que les clans ne s'uniront jamais.]=],
		},
		{
			title = "Hauts faits",
			text = [=[• Il remet des instructions écrites à ceux qui acceptent d'entrer dans Maraudon pour lui.
• Il entend commencer la grande tâche d'unir les tribus.]=],
		},
	},
	chapters = {
		{
			title = "Une seule grande tribu",
			hint = "Faites ce que le Paria demande dans les salles de Maraudon.",
			text = [=[L'étranger entra dans la tombe et en revint avec ce dont le Paria avait besoin. Il exulta. Maintenant, dit-il, la grande œuvre pouvait commencer. Il paya celui qui l'avait aidé et espéra que, lorsqu'ils se reverraient, ce serait dans des termes bien différents. Nul ne peut encore dire quels seront ces termes.]=],
		},
	},
	mentions = {
