Translate("frFR", "uthek-the-wise", {
	title = "Uthek la Sage",
	subtitle = "Chamane des Gelkis",
	found = "Les abords du Village des Gelkis",
	hint = [=[Cherchez la chamane des Gelkis qui entend les murmures de la terre.]=],
	allegiance = "Clan Gelkis",
	aliases = { "Uthek" },
	sections = {
		{
			title = "Résumé",
			text = [=[Uthek la Sage est une chamane du clan Gelkis, et elle parle pour son peuple aux rares étrangers qu'il tolère. Elle écoute la terre, et la terre lui répond : elle lui dit quand les Magram s'affaiblissent, où se trouve un cristal lointain, et quelles mains sont trempées du sang des Magram. Elle croit que la magie de la terre est plus forte que la force de n'importe quel guerrier, et que les Gelkis régneront un jour sur {link:desolace}Désolace{/link}.]=],
		},
		{
			title = "Importance",
			text = [=[Uthek est la voix de la foi des centaures en Theradras. Par elle, les Gelkis acceptent l'aide de l'{link:alliance}Alliance{/link} comme de la {link:horde}Horde{/link}, et par elle ces étrangers sont entraînés dans une guerre de clans plus ancienne que leurs propres nations.]=],
		},
		{
			title = "Hauts faits",
			text = [=[• Elle met les étrangers à l'épreuve d'après les Magram qu'ils ont tués.
• Elle les envoie piller les réserves de viande des Magram et briser l'orgueil des {link:kolkar-centaurs}Kolkar{/link}.
• Elle convoite la draenéthyste, un cristal rouge nouveau dans la terre d'{link:azeroth}Azeroth{/link}, qui vient, dit-elle, d'une terre où les montagnes volent et où règnent les démons.
• Elle réclame la mort du khan {link:khan-jehn}Jehn{/link} des Magram et du khan {link:khan-hratha}Hratha{/link} des Maraudine.]=],
		},
	},
	chapters = {
		{
			title = "Une amie des Gelkis",
			hint = "Gagnez la confiance de la chamane des Gelkis.",
			text = [=[Uthek ne salue pas les étrangers. Elle attend que la terre lui dise qu'ils ont tué beaucoup de Magram, et alors elle parle. Ses premiers mots sont une offre : qu'ils lui disent ce qu'ils peuvent faire pour les Gelkis, et elle leur dira ce que les Gelkis peuvent faire pour eux.]=],
		},
		{
			title = "L'éclat de l'égaré",
			hint = [=[Apportez à la chamane le cristal rouge qu'elle entend dans la terre.]=],
			text = [=[La terre murmura à Uthek l'existence d'un cristal appelé draenéthyste, détenu par un égaré nommé {link:ongeku}Ongeku{/link} dans {link:swamp-of-sorrows}le Marais des Chagrins{/link}. Quand l'éclat fut déposé entre ses mains, elle sentit aussitôt sa puissance, et elle jura de la retourner contre les ennemis de son clan.]=],
		},
		{
			title = "La chute des khans",
			hint = "Abattez les khans que la chamane désigne.",
			text = [=[Le khan {link:khan-jehn}Jehn{/link} était fort et insensé, dit Uthek, car il ne voyait pas que la magie de la terre était plus forte que son bras. Quand il tomba, elle désigna ensuite le khan des Maraudine. {link:khan-hratha}Hratha{/link} portait un fragment de clé, et elle le voulait. Quand il fut mort lui aussi, elle promit que les esprits de la terre chanteraient le nom de celui qui l'avait tué.]=],
		},
	},
	mentions = {
		{ text = "{link:alliance}Alliance{/link} avec les Gelkis" },
		{ text = "Une étrange alliance" },
		{ text = "Raid contre les {link:kolkar-centaurs}Kolkar{/link}" },
		{ text = "Voler des provisions" },
		{ text = "{link:ongeku}Ongeku{/link}" },
		{ text = "{link:khan-jehn}Khan Jehn{/link}" },
		{ text = "{link:khan-hratha}Khan Hratha{/link}" },
	},
	bonds = {
		{ id = "khan-shaka", name = "Khan Shaka", note = "son khan" },
		{ id = "warug", name = "Warug", note = "l'ennemi de son clan" },
		{ id = "khan-jehn", name = "Khan Jehn", note = "elle voulait sa tête" },
		{ id = "khan-hratha", name = "Khan Hratha", note = "elle voulait sa tête" },
	},
})

Translate("frFR", "warug", {
	title = "Warug",
	subtitle = "Porte-parole des Magram",
	found = "Les abords du Village des Magram",
	hint = [=[Cherchez le Magram qui parle pour son clan à la lisière de leur village.]=],
	allegiance = "Clan Magram",
	sections = {
		{
			title = "Résumé",
			text = [=[Warug parle pour les Magram aux rares étrangers qui gagnent le droit de l'entendre. Il est bruyant, cruel et fier. Les Magram n'ont besoin d'aucune protection, dit-il, ni de Theradras ni de personne, parce qu'ils sont les plus forts. Il rit quand il tue, et il dit aux autres d'en faire autant, afin que leurs ennemis voient combien ils sont faibles.]=],
		},
		{
			title = "Importance",
			text = [=[Warug est le credo des Magram fait chair : la force avant la foi, et le rire sur les morts. Il prouve aussi que les Magram, malgré tout leur mépris, acceptent l'aide d'étrangers quand elle les sert.]=],
		},
		{
			title = "Hauts faits",
			text = [=[• Il met les étrangers à l'épreuve d'après les Gelkis qu'ils ont tués.
• Il les envoie briser les larmes de Theradras amassées par les Gelkis.
• Il réclame la mort du khan {link:khan-shaka}Shaka{/link} des Gelkis et du khan {link:khan-hratha}Hratha{/link} des Maraudine.
• Il tua jadis un marchand {link:gnomes}gnome{/link} venu en {link:desolace}Désolace{/link}, mais garda un jouet de la charrette du gnome parce qu'il le faisait rire.]=],
		},
	},
	chapters = {
		{
			title = "Un ami des Magram",
			hint = "Gagnez le respect du porte-parole des Magram.",
			text = [=[Les Magram ne parlent pas aux faibles. Ils les tuent. Warug refusa de dire quoi que ce soit tant que les Gelkis ne pleuraient pas au nom d'un étranger. Alors il admit que l'étranger était peut-être fort comme les Magram, et que peut-être les Magram et l'étranger pouvaient être amis.]=],
		},
		{
			title = "Les larmes de Theradras",
			hint = "Brisez ce que les Gelkis croient être leur protection.",
			text = [=[Dans une grotte de leur village, les Gelkis gardaient des cristaux qu'ils appelaient les larmes de Theradras. Warug voulait qu'ils soient brisés et que les morceaux lui soient apportés. Si les larmes se brisaient, dit-il, les Gelkis apprendraient que leur mère ne les aiderait pas, et qu'elle ne pleurerait même pas quand les Magram les écraseraient.]=],
		},
		{
			title = "La tête de Shaka",
			hint = "Abattez les khans que Warug désigne.",
			text = [=[Quand le khan {link:khan-shaka}Shaka{/link} tomba, Warug planta sa tête sur une pique et la garda près de lui, afin que Shaka puisse regarder les Magram devenir forts. Il envoya ensuite ses amis contre {link:khan-hratha}Hratha{/link} des Maraudine. Quand ce khan mourut à son tour, Warug promit que celui qui l'avait aidé serait épargné par les sabots des Magram quand tous les autres seraient piétinés.]=],
		},
	},
	mentions = {
		{ text = "{link:alliance}Alliance{/link} avec les Magram" },
		{ text = "Politique brutale" },
		{ text = "Assaut contre les {link:kolkar-centaurs}Kolkar{/link}" },
		{ text = "Larmes brisées" },
		{ text = "Un gadget pour Warug" },
		{ text = "{link:khan-shaka}Khan Shaka{/link}" },
		{ text = "{link:khan-hratha}Khan Hratha{/link}" },
	},
	bonds = {
		{ id = "khan-jehn", name = "Khan Jehn", note = "son khan" },
		{ id = "uthek-the-wise", name = "Uthek la Sage", note = "l'ennemie de son clan" },
		{ id = "khan-shaka", name = "Khan Shaka", note = "il voulait sa tête" },
		{ id = "khan-hratha", name = "Khan Hratha", note = "il voulait sa tête" },
	},
})

