Translate("frFR", "azore-aldamort", {
	title = "Azore Aldamort",
	subtitle = "Mage de l'Aube d'argent",
	found = "Une colline au-dessus d'Ethel Rethor",
	hint = [=[Cherchez le mage qui surveille les nagas et la Lame ardente depuis les collines d'Ethel Rethor.]=],
