	sections = {
		{
			title = "Résumé",
			text = [=[Azore Aldamort est un mage qui monte la garde depuis les collines d'{link:ethel-rethor}Ethel Rethor{/link}. Il a appris que la {link:burning-blade}Lame ardente{/link} a pris aux nagas une relique appelée le Sceptre de Lumière, qui, selon la légende, peut engloutir des cités entières sous la mer. Il est résolu à ce que les cultistes ne la gardent pas. Il cherche aussi les propres secrets des nagas, conservés depuis des siècles dans un Livre des Anciens.]=],
		},
		{
