		},
		{
			title = "Hauts faits",
			text = [=[• Il cherche à obtenir le Sceptre de Lumière auprès du voyant de la {link:burning-blade}Lame ardente{/link} de la {link:thunder-axe-fortress}Forteresse de Hache-Tonnerre{/link}.
• Il envoie la Gemme du Serpent à l'{link:ranazjar-isle}Ile de Ranazjar{/link} pour invoquer le gardien du Livre des Anciens, et transmet le livre à un haut conseil.]=],
		},
	},
	mentions = {
		{ text = "Le Sceptre de Lumière" },
		{ text = "Le Livre des Anciens" },
	},
	bonds = {
		{ id = "willow", name = "Willow", note = "un autre chercheur d'anciennes puissances en Désolace" },
	},
})

Translate("frFR", "willow", {
	title = "Willow",
	subtitle = "Agent du Marteau du crépuscule",
