	},
	bonds = {
		{ id = "azore-aldamort", name = "Azore Aldamort", note = "un autre chercheur d'anciennes puissances" },
	},
})

Translate("frFR", "bibbly-f-utzbuckle", {
	title = "Bibbly F'utzbuckle",
	subtitle = "Marchand d'os gobelin",
	found = "Un camp au nord du Cimetière des kodos",
	hint = [=[Trouvez le gobelin qui croit que les os de kodo feront sa fortune.]=],
	allegiance = "Marchand gobelin",
	aliases = { "Bibbly" },
	sections = {
		{
			title = "Résumé",
			text = [=[Bibbly F'utzbuckle est un gobelin qui a trouvé sa fortune dans le {link:kodo-graveyard}Cimetière des kodos{/link}. Les os de kodo, dit-il, vont changer le monde : ses clients en font des meubles, des instruments et même de la poudre explosive. Une caravane ramasse ses os et les vend à {link:shadowprey-village}Proie-de-l'Ombre{/link}. Bibbly rêve d'être le gobelin le plus riche du monde, ne serait-ce que pour prouver que son ancien maître avait tort.]=],
		},
		{
			title = "Importance",
			text = [=[Bibbly montre comment les gobelins voient {link:desolace}Désolace{/link}. Là où d'autres voient un cimetière, il voit une mine.]=],
		},
		{ title = "Hauts faits", text = "• Il achète des os de kodo au cimetière situé au sud." },
	},
	mentions = {
		{ text = "Le collectionneur d'os" },
	},
